namespace RonSijm.FluidHumidifier.Factories.QuickSight;

public class TopicV2Factory(string resourceName = null, Action<Humidifier.QuickSight.TopicV2> factoryAction = null) : ResourceFactory<Humidifier.QuickSight.TopicV2>(resourceName)
{

    internal List<InnerTopicV2DataSetRelationFactory> DataSetRelationsFactories { get; set; } = [];

    internal List<InnerTopicV2DataSetReferenceFactory> DataSetsFactories { get; set; } = [];

    internal List<InnerTopicV2ResourcePermissionFactory> PermissionsFactories { get; set; } = [];

    internal InnerTopicV2CustomInstructionsFactory CustomInstructionsFactory { get; set; }

    protected override Humidifier.QuickSight.TopicV2 Create()
    {
        var topicV2Result = CreateTopicV2();
        factoryAction?.Invoke(topicV2Result);

        return topicV2Result;
    }

    private Humidifier.QuickSight.TopicV2 CreateTopicV2()
    {
        var topicV2Result = new Humidifier.QuickSight.TopicV2
        {
            GivenName = InputResourceName,
        };

        return topicV2Result;
    }
    public override void CreateChildren(Humidifier.QuickSight.TopicV2 result)
    {
        base.CreateChildren(result);

        result.DataSetRelations = DataSetRelationsFactories.Any() ? DataSetRelationsFactories.Select(x => x.Build()).ToList() : null;
        result.DataSets = DataSetsFactories.Any() ? DataSetsFactories.Select(x => x.Build()).ToList() : null;
        result.Permissions = PermissionsFactories.Any() ? PermissionsFactories.Select(x => x.Build()).ToList() : null;
        result.CustomInstructions ??= CustomInstructionsFactory?.Build();
    }

} // End Of Class

